import java.io.*;import java.util.*;import com.koios.client.arpg.ChatWrap;import com.koios.client.graphic.TextDrawingArea;import com.koios.client.cache.Decompressor;import com.koios.client.stream.StreamLoader;
public class ChatWrapCheck {
 public static void main(String[] args)throws Exception{try(RandomAccessFile data=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile index=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){TextDrawingArea font=new TextDrawingArea(false,"p12_full",new StreamLoader(new Decompressor(data,index,1).decompress(1)));String message="Your guided tutorial will move you between stations. Complete each instruction to continue. Open inventory and wear both your starter sword and body armour before moving to the next station.";List<String> lines=ChatWrap.lines(message,480,font::getTextWidth);if(lines.size()<2)throw new AssertionError("Long chat must wrap");for(String line:lines)if(font.getTextWidth(line)>480)throw new AssertionError("Clipped line: "+line);if(!String.join(" ",lines).equals(message))throw new AssertionError("Text lost while wrapping");if(ChatWrap.lines("First\nSecond",480,font::getTextWidth).size()!=2)throw new AssertionError("Explicit newline lost");String word=String.join("",Collections.nCopies(150,"W"));for(String line:ChatWrap.lines(word,480,font::getTextWidth))if(font.getTextWidth(line)>480)throw new AssertionError("Long word clips");System.out.println("Chat wrapping verified with the actual cache font.");}}
}
